import {makeHero,createItem,uid,derive,clamp,equip} from './rules.js?v=0.3.1';
import {CLASSES,EFFECTS} from '../content/classes.js?v=0.3.1';import {ITEM_TEMPLATES,ZONES} from '../content/region.js?v=0.3.1';
export const SAVE_KEY='vyriy-save-v2';
export function migrateV1(old,classId='swordsman',name='Мандрівник'){let base=old.heroes?.[0];let h=makeHero(classId,name);if(!base)return h;h.level=clamp(Math.floor(base.base||1),1,85);h.skillPoints=2+h.level-1;h.xp=Math.max(0,base.xp||0);h.zeny=Math.max(0,old.zeny||0);let spent=0;for(let k of Object.keys(h.stats)){let oldVal=clamp(Math.floor(base.stats?.[k]||4),1,99);h.stats[k]=Math.max(h.stats[k],oldVal);spent+=Math.max(0,h.stats[k]-CLASSES[classId].stat[k]);}h.statPoints=Math.max(0,5+(h.level-1)*5-spent);for(let [id,n]of Object.entries(old.inventory||{})){let template=ITEM_TEMPLATES[id]?id:id.startsWith('card:')?'rune':null;if(template)for(let j=0;j<Math.min(500,Math.max(0,n));j++)h.inventory.push(createItem(template,h.id));}for(let template of Object.values(base.gear||{})){if(ITEM_TEMPLATES[template]){let item=createItem(template,h.id);h.inventory.push(item);equip(h,item.id);}}for(let card of Object.values(base.cards||{}))if(card)h.inventory.push(createItem('rune',h.id));let d=derive(h);h.hp=d.hp;h.sp=d.sp;return h;}
export function loadSave(){try{let raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;let s=JSON.parse(raw);if(![2,3].includes(s.version)||!s.players||!ZONES[s.zone])return null;return upgradeSave(s);}catch{return null;}}
export function saveLocal(s){try{localStorage.setItem(SAVE_KEY,JSON.stringify(s));return true}catch{return false}}
export function getLegacy(){try{return JSON.parse(localStorage.getItem('vyriy-save-v1'))}catch{return null}}
export function validateImported(s){if(![2,3].includes(s?.version)||!ZONES[s.zone]||!s.players||Object.keys(s.players).length!==1||!Array.isArray(s.enemies)||!Array.isArray(s.claims)||!s.flags||!Array.isArray(s.flags.seals))throw Error('Невірне збереження');let h=Object.values(s.players)[0];if(!CLASSES[h.classId]||typeof h.name!=='string'||!h.inventory||h.inventory.length>10000||!h.stats||!h.equipment||!Array.isArray(h.effects)||!h.cooldowns||!h.specs)throw Error('Невірний герой');for(let n of ['level','xp','hp','sp','statPoints','zeny','x','y'])if(!Number.isFinite(h[n])||h[n]<0)throw Error('Невірні характеристики');if(h.level<1||h.level>85)throw Error('Невірний рівень');for(let n of Object.keys(CLASSES[h.classId].stat))if(!Number.isFinite(h.stats[n])||h.stats[n]<1||h.stats[n]>99)throw Error('Невірні характеристики');let ids=new Set;for(let item of h.inventory){if(!ITEM_TEMPLATES[item.template]||typeof item.id!=='string'||ids.has(item.id)||item.owner!==h.id)throw Error('Невірні предмети');ids.add(item.id);}h.effects=h.effects.filter(e=>EFFECTS[e.id]&&Number.isFinite(e.left)&&e.left>0&&e.left<120&&Number.isFinite(e.stacks)&&e.stacks>=1&&e.stacks<=3);s.events=[];return upgradeSave(s);}

export function upgradeSave(s){let previous=s.version;s.version=3;s.flags??={seals:[]};s.flags.zoneBosses??={};if(s.flags.boss)s.flags.zoneBosses.crypt=true;if(s.flags.seals?.length===3)s.flags.sealsReady=true;for(let h of Object.values(s.players||{})){let c=CLASSES[h.classId];h.skillPoints??=2+Math.max(0,h.level-1);h.skillRanks??=Object.fromEntries(c.skills.map((a,i)=>[a.id,i<2?1:0]));for(let a of c.skills)h.skillRanks[a.id]??=0;h.skillbar??=c.skills.slice(0,2).map(a=>a.id);h.equipment.accessory??=null;h.quests??={};h.counters??={};for(let item of h.inventory)item.rarity??=ITEM_TEMPLATES[item.template]?.rarity||'common';}if(previous===2){s.contentRevision=2;s.projectiles=[];for(let h of Object.values(s.players||{})){h.cast=null;h.target=null;h.auto=false;}}return s;}
